//#region lib/challenge.ts
function createGnoChallenge(resource, method = "GET") {
	const payTo = process.env.G402_MERCHANT_ADDRESS || `g1${"q".repeat(38)}`;
	if (!process.env.G402_MERCHANT_ADDRESS) throw new Error("merchant_address_required");
	return PaymentRequirementsSchema.parse({
		scheme: "exact",
		network: process.env.GNO_NETWORK_ID || "gno:staging",
		asset: process.env.GNO_ASSET || "gno.land/r/gnoland/wugnot",
		amount: process.env.G402_SAMPLE_PRICE || "1000",
		payTo,
		maxTimeoutSeconds: 300,
		resource,
		description: "g402 staging paid weather sample",
		mimeType: "application/json",
		extra: {
			chainId: process.env.GNO_CHAIN_ID || "staging",
			denom: process.env.GNO_DENOM || "ugnot",
			resourceHash: resourceHash(method, resource),
			expiresAt: Math.floor(Date.now() / 1e3) + 300,
			nonce: crypto.randomUUID().replaceAll("-", "")
		}
	});
}
function paymentRequiredHeader(requirements) {
	return Buffer.from(JSON.stringify({
		x402Version: 2,
		accepts: [requirements]
	})).toString("base64url");
}
